            'createArticleObject'     => $this->client->post($p['token'], '/article-object/', $this->bodyFrom($p, ['org', 'billing_account', 'name', 'description', 'has_unlimited_pieces', 'pieces', 'reserved_pieces', 'selling_price', 'tax_rate', 'tax_name', 'cost_centre', 'sphere', 'gross', 'location_object', 'delete_after_date', 'deleted_by', 'identifier', 'picture', 'purchase_price', 'location_name'])),
            'updateArticleObject'     => $this->client->patch($p['token'], '/article-object/' . $p['id'] . '/', $this->bodyFrom($p, ['org', 'billing_account', 'name', 'description', 'has_unlimited_pieces', 'pieces', 'reserved_pieces', 'selling_price', 'tax_rate', 'tax_name', 'cost_centre', 'sphere', 'gross', 'location_object', 'delete_after_date', 'deleted_by', 'identifier', 'picture', 'purchase_price', 'location_name'])),
            'deleteArticleObject'     => $this->deleted($p['token'], '/article-object/' . $p['id'] . '/', 'ArticleObject'),
            'listFeatureRequests'     => $this->client->get($p['token'], '/feature-request/', $this->pagination($p)),
            'getFeatureRequest'       => $this->client->get($p['token'], '/feature-request/' . $p['id'] . '/'),
            'createFeatureRequest'    => $this->client->post($p['token'], '/feature-request/', $this->bodyFrom($p, ['title', 'description', 'category'])),
            'deleteFeatureRequest'    => $this->deleted($p['token'], '/feature-request/' . $p['id'] . '/', 'FeatureRequest'),
            'listUpdateHighlights'    => $this->client->get($p['token'], '/update-highlight/', $this->pagination($p)),
            'getUpdateHighlight'      => $this->client->get($p['token'], '/update-highlight/' . $p['id'] . '/'),
            'createUpdateHighlight'   => $this->client->post($p['token'], '/update-highlight/', $this->bodyFrom($p, ['title', 'version', 'release_date', 'is_public'])),
            'updateUpdateHighlight'   => $this->client->patch($p['token'], '/update-highlight/' . $p['id'] . '/', $this->bodyFrom($p, ['title', 'version', 'release_date', 'is_public'])),
            'deleteUpdateHighlight'   => $this->deleted($p['token'], '/update-highlight/' . $p['id'] . '/', 'UpdateHighlight'),
            'listUpdateHighlightEntries'   => $this->client->get($p['token'], '/update-highlight-entry/', $this->pagination($p)),
            'getUpdateHighlightEntry'      => $this->client->get($p['token'], '/update-highlight-entry/' . $p['id'] . '/'),
            'createUpdateHighlightEntry'   => $this->client->post($p['token'], '/update-highlight-entry/', $this->bodyFrom($p, ['title', 'body', 'update_highlight'])),
            'updateUpdateHighlightEntry'   => $this->client->patch($p['token'], '/update-highlight-entry/' . $p['id'] . '/', $this->bodyFrom($p, ['title', 'body', 'update_highlight'])),
            'deleteUpdateHighlightEntry'   => $this->deleted($p['token'], '/update-highlight-entry/' . $p['id'] . '/', 'UpdateHighlightEntry'),
            'resetPassword'           => $this->client->post($p['token'], '/reset-password/', $this->bodyFrom($p, ['email', 'short'])),
            'normalize'               => $this->client->post($p['token'], '/normalize/', $this->bodyFrom($p, ['member'])),
            'getToken'                => $this->client->post($p['token'], '/get-token/', $this->bodyFrom($p, ['username', 'password', '2FA'])),
            default => throw new \InvalidArgumentException("Unknown tool: $name"),
        };
    }

}
